function aux(x, a, b, i, vis) {
    const stack = [i];
    while (stack.length > 0) {
        i = stack.pop();
        if (i - b >= 0 && !vis.has(i - b)) {
            vis.add(i - b);
            stack.push(i - b);
        }
        if (i + a <= x && !vis.has(i + a)) {
            vis.add(i + a);
            stack.push(i + a);
        }
    }
}

function single(x, a, b, vis) {
    if (vis.has(x - a)) {
        vis.add(x);
        aux(x, a, b, x, vis);
    }
    return vis.size;
}

function sum_seq(n) {
    return n * (n + 1) / 2;
}

function solve(m, a, b) {
    const vis = new Set([0]);
    let tot = 0;
    for (let i = 0; i <= m; i++) {
        const one = single(i, a, b, vis);
        tot += one;
        if (i > 0 && one === i + 1) {
            return tot + sum_seq(m + 1) - sum_seq(i + 1);
        }
    }
    return tot;
}

function gcd(a, b) {
    while (b > 0) {
        const t = b;
        b = a % b;
        a = t;
    }
    return a;
}

