    const g = gcd(a, b);
    const first = Math.min(m, a + b);
    const vis = new Set([0]);
    let tot = 0;
    let ct = 0;
    for (let i = 0; i <= first; i++) {
        ct = single(i, a, b, vis);
        tot += ct;
    }
    const diff = m - first;
    tot += g * (sum_seq(Math.floor(diff / g) + ct) - sum_seq(ct));
    if (Math.floor(diff / g) > 0) {
        tot -= (Math.floor(diff / g) + ct) * ((g - 1) - (diff % g));
    }
    tot += ct * Math.min(g - 1, diff);
    return tot;
}

